package ai.eva.android.probe;
import java.io.*;import java.net.*;import java.nio.*;import java.util.*;
/** Bounded offline classic-PCAP metadata decoder. Does not decrypt TLS. */
final class PacketSummary {
 static final class Flow {String source,destination,protocol,sni="",http="";int sourcePort,destinationPort,packets;long bytes;boolean tls;}
 final Map<String,Flow> flows=new LinkedHashMap<>();final Set<String> dns=new LinkedHashSet<>();int packets,linkType;long capturedBytes;boolean truncated;
 static int u16(byte[] b,int p){return ((b[p]&255)<<8)|(b[p+1]&255);}static long u32(byte[] b,int p,boolean little){long value=0;for(int n=0;n<4;n++)value=(value<<8)|(b[p+(little?3-n:n)]&255);return value;}
 static PacketSummary read(File f)throws Exception{if(f.length()>32L*1024*1024)throw new IOException("PCAP 超过 32 MB 分析上限");PacketSummary summary=new PacketSummary();try(DataInputStream in=new DataInputStream(new BufferedInputStream(new FileInputStream(f)))){byte[] h=new byte[24];in.readFully(h);long magic=u32(h,0,false);boolean little=magic==0xd4c3b2a1L||magic==0x4d3cb2a1L;if(!little&&magic!=0xa1b2c3d4L&&magic!=0xa1b23c4dL)throw new IOException("不支持的 PCAP 格式（请选择经典 PCAP，而非 PCAPNG）");summary.linkType=(int)u32(h,20,little);byte[] record=new byte[16];while(in.available()>0){if(summary.packets>=100000){summary.truncated=true;break;}if(in.available()<16){summary.truncated=true;break;}in.readFully(record);long count=u32(record,8,little);if(count>262144||count>in.available()){summary.truncated=true;break;}byte[] frame=new byte[(int)count];in.readFully(frame);summary.packets++;summary.capturedBytes+=count;summary.packet(frame);}}return summary;}
 void packet(byte[] b){try{int p=linkType==101||linkType==228||linkType==229?0:linkType==1?14:linkType==113?16:linkType==276?20:-1;if(p<0||b.length<p+20)return;if(linkType==1&&u16(b,12)==0x8100)p+=4;int version=(b[p]&255)>>4,protocol,transport;byte[] src,dst;if(version==4){int header=(b[p]&15)*4;if(header<20||b.length<p+header)return;if((u16(b,p+6)&0x1fff)!=0)return;protocol=b[p+9]&255;src=Arrays.copyOfRange(b,p+12,p+16);dst=Arrays.copyOfRange(b,p+16,p+20);transport=p+header;}else if(version==6){if(b.length<p+40)return;protocol=b[p+6]&255;src=Arrays.copyOfRange(b,p+8,p+24);dst=Arrays.copyOfRange(b,p+24,p+40);transport=p+40;for(int n=0;n<8&&(protocol==0||protocol==43||protocol==60);n++){if(transport+2>b.length)return;int len=((b[transport+1]&255)+1)*8;protocol=b[transport]&255;transport+=len;}if(protocol==44)return;}else return;if((protocol!=6&&protocol!=17)||transport+8>b.length)return;int sport=u16(b,transport),dport=u16(b,transport+2),payload;if(protocol==6){if(transport+20>b.length)return;int length=((b[transport+12]&255)>>4)*4;if(length<20)return;payload=transport+length;}else payload=transport+8;if(payload>b.length)return;String source=InetAddress.getByAddress(src).getHostAddress(),destination=InetAddress.getByAddress(dst).getHostAddress(),name=protocol==6?"TCP":"UDP",key=source+":"+sport+">"+destination+":"+dport+"/"+name;Flow flow=flows.get(key);if(flow==null){if(flows.size()>=200){truncated=true;return;}flow=new Flow();flow.source=source;flow.destination=destination;flow.sourcePort=sport;flow.destinationPort=dport;flow.protocol=name;flows.put(key,flow);}flow.packets++;flow.bytes+=b.length;if(protocol==17&&(sport==53||dport==53)&&payload+12<b.length){String domain=dnsName(b,payload+12);if(!domain.isEmpty()&&dns.size()<100)dns.add(domain);}if(protocol==6&&payload+5<b.length){int first=b[payload]&255;if((first==22||first==23)&&b[payload+1]==3){flow.tls=true;String sni=sni(b,payload);if(!sni.isEmpty())flow.sni=sni;}if(flow.http.isEmpty()){String prefix=new String(b,payload,Math.min(256,b.length-payload),java.nio.charset.StandardCharsets.ISO_8859_1);if(prefix.matches("(?s)^(GET|POST|HEAD|PUT|DELETE|OPTIONS|PATCH) .*")){String line=prefix.split("\\r?\\n",2)[0],method=line.substring(0,line.indexOf(' '));flow.http=method+" [HTTP 明文请求；路径与头部未展示]";}}}}catch(Exception ignored){}}
 static String dnsName(byte[] b,int p){StringBuilder s=new StringBuilder();for(int n=0;n<40&&p<b.length;n++){int len=b[p++]&255;if(len==0)break;if(len>63||p+len>b.length)return "";if(s.length()>0)s.append('.');for(int i=0;i<len;i++){char c=(char)(b[p++]&255);if(!Character.isLetterOrDigit(c)&&c!='-'&&c!='_')return "";s.append(c);}if(s.length()>253)return "";}return s.toString();}
 static String sni(byte[] b,int p){try{if((b[p]&255)!=22||p+44>=b.length||b[p+5]!=1)return "";int end=Math.min(b.length,p+5+u16(b,p+3)),at=p+43;at+=1+(b[at]&255);if(at+2>end)return "";at+=2+u16(b,at);if(at>=end)return "";at+=1+(b[at]&255);if(at+2>end)return "";int exEnd=Math.min(end,at+2+u16(b,at));at+=2;while(at+4<=exEnd){int type=u16(b,at),length=u16(b,at+2);at+=4;if(at+length>exEnd)return "";if(type==0&&length>=5){int pos=at+2;if(b[pos]==0){int len=u16(b,pos+1);if(pos+3+len<=at+length){String name=new String(b,pos+3,len,java.nio.charset.StandardCharsets.US_ASCII);return name.matches("[A-Za-z0-9.-]{1,253}")?name:"";}}}at+=length;}}catch(Exception ignored){}return "";}
 static String quote(String s){return "\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t")+"\"";}
 String json(){StringBuilder out=new StringBuilder("{\"packets\":").append(packets).append(",\"capturedBytes\":").append(capturedBytes).append(",\"linkType\":").append(linkType).append(",\"truncated\":").append(truncated).append(",\"tlsDecrypted\":false,\"dns\":[");int n=0;for(String d:dns){if(n++>0)out.append(',');out.append(quote(d));}out.append("],\"flows\":[");n=0;for(Flow f:flows.values()){if(n++>0)out.append(',');out.append("{\"source\":").append(quote(f.source)).append(",\"destination\":").append(quote(f.destination)).append(",\"protocol\":").append(quote(f.protocol)).append(",\"sourcePort\":").append(f.sourcePort).append(",\"destinationPort\":").append(f.destinationPort).append(",\"packets\":").append(f.packets).append(",\"bytes\":").append(f.bytes).append(",\"tlsRecordObserved\":").append(f.tls).append(",\"sni\":").append(quote(f.sni)).append(",\"http\":").append(quote(f.http)).append('}');}return out.append("]}").toString();}
}
